"""Build the QA workbook with Python's standard library. Run from the project root."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape
from collections import Counter
from datetime import date
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/learning/artifacts/site-automation-plan-detailed.xlsx'
NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
features = []

def feature(name, story, sources, target):
    f = dict(name=name, story=story, sources=sources, target=target, cases=[])
    features.append(f)
    return f

def case(f, id, priority, story, conditions, steps, expected, note='', status='Заплановано', result='Не запускали', proof=''):
    f['cases'].append([id, priority, story, conditions, steps, expected, status, result, proof or ('План: '+f['target']), note])

