# OOXML spreadsheet writer: keeps formulas, dropdowns, filters, and internal navigation.
def col(n):
    s=''
    while n:
        n,r=divmod(n-1,26); s=chr(65+r)+s
    return s

def sheet_xml(s):
    parts=[f'<worksheet xmlns="{NS}" xmlns:r="{REL}">']
    split=s['freeze']; first=split+1
    parts.append(f'<sheetViews><sheetView workbookViewId="0" zoomScale="80">'+(f'<pane xSplit="2" ySplit="{split}" topLeftCell="C{first}" activePane="bottomRight" state="frozen"/>' if split else '')+'</sheetView></sheetViews>')
    parts.append('<sheetFormatPr defaultRowHeight="24"/><cols>')
    parts += [f'<col min="{i}" max="{i}" width="{w}" customWidth="1"/>' for i,w in enumerate(s['widths'],1)]
    parts.append('</cols><sheetData>')
    for rn,row in enumerate(s['rows'],1):
        height=36 if rn<=split else 105
        if s['name']=='00 Початок і прогрес': height=36 if rn<=11 else 38
        if s['name']=='14 Карта коду' and rn>4: height=120
        cells=[]
        for cn,val in enumerate(row,1):
            addr=f'{col(cn)}{rn}'; style=0
            if isinstance(val,tuple) and val[0]=='formula':
                cells.append(f'<c r="{addr}" s="4"><f>{escape(val[1])}</f><v>{val[2]}</v></c>');continue
            if isinstance(val,tuple): _,val,style=val
            elif isinstance(val,int):
                cells.append(f'<c r="{addr}" s="4"><v>{val}</v></c>');continue
            elif rn>split:
                style=2 if rn%2==0 else 0
                if cn==1:style=6
                if len(row)==10 and cn==2:style=3 if val=='P0' else 5
            cells.append(f'<c r="{addr}" t="inlineStr" s="{style}"><is><t xml:space="preserve">{escape(str(val))}</t></is></c>')
        parts.append(f'<row r="{rn}" ht="{height}" customHeight="1">'+''.join(cells)+'</row>')
    parts.append('</sheetData>')
    if s['filter_ref']: parts.append(f'<autoFilter ref="{s["filter_ref"]}"/>')
    if s['merges']: parts.append(f'<mergeCells count="{len(s["merges"])}">'+''.join(f'<mergeCell ref="{r}"/>' for r in s['merges'])+'</mergeCells>')
    for priority,(ref,form,dxf) in enumerate(s['conditional'],1):
        parts.append(f'<conditionalFormatting sqref="{ref}"><cfRule type="expression" dxfId="{dxf}" priority="{priority}"><formula>{escape(form)}</formula></cfRule></conditionalFormatting>')
    if s['validations']:
        parts.append(f'<dataValidations count="{len(s["validations"])}">')
        for ref,choices in s['validations']:
            parts.append(f'<dataValidation type="list" allowBlank="0" showErrorMessage="1" errorTitle="Оберіть статус" error="Використайте значення зі списку." sqref="{ref}"><formula1>{escape(choices)}</formula1></dataValidation>')
        parts.append('</dataValidations>')
    if s['links']:
        parts.append('<hyperlinks>')
        parts += [f'<hyperlink ref="{addr}" location="{escape(dest, {chr(34): "&quot;"})}"/>' for addr,dest in s['links'].items()]
        parts.append('</hyperlinks>')
    parts.append('<pageMargins left="0.25" right="0.25" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup paperSize="8" orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>')
    return ''.join(parts)

