import sys
if OUT.exists() and '--overwrite' not in sys.argv:
    raise SystemExit('Workbook already exists. Edit progress in Excel; use --overwrite only to reset it deliberately.')
OUT.parent.mkdir(parents=True,exist_ok=True)
with ZipFile(OUT,'w',ZIP_DEFLATED) as z:
    for name,xml in parts.items(): z.writestr(name,'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+xml)
with ZipFile(OUT) as z:
    assert z.testzip() is None
    for name in z.namelist(): ET.fromstring(z.read(name))
print(f'Created {OUT.name}: {len(sheets)} sheets, {len(allcases)} checks, {dict(counts)}, 2 existing UI tests.')
print('Validated XML, ZIP, unique IDs, statuses, source paths, existing test evidence, and cached summary counts.')
